import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 변경 항목 이름과 인사기록카드 컬럼의 대응 (허용된 변경 항목만 신청할 수 있다)
const ITEM_COLUMNS: Record<string, string> = {
  '주소': 'address_enc',
  '주민등록번호': 'resident_number_enc',
  '보훈정보': 'veteran_info',
  '병역정보': 'military_service_info',
  '채용구분': 'recruitment_type',
  '채용비고': 'recruitment_note',
};
// 가정: 알림 채널은 기본 채널인 포털
const NOTIFY_CHANNEL = '포털';
// 가정: 개인정보 암호화는 저장 계층이 맡는다. 이 컨트롤러는 받은 값을 _enc 컬럼에 그대로 저장한다.

function text(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const trimmed = value.trim();
  return trimmed === '' ? null : trimmed;
}

@Controller('api/v1')
export class FnSfr01202Controller {
  @Get('/personnel-change-requests')
  async listPersonnelChangeRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    let size = sizeRaw === undefined || sizeRaw === '' ? 20 : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기가 올바르지 않습니다.');
    }
    if (size > 200) {
      size = 200;
    }
    const status = text(query['status']);
    if (status !== null && !['신청', '승인', '반려'].includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 처리 상태 값이 올바르지 않습니다.');
    }
    const employeeRaw = text(query['employeeId']);
    if (employeeRaw !== null && !/^[0-9]+$/.test(employeeRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 임직원 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const params = { status, employeeId: employeeRaw, size, offset: page * size };
      const where = 'WHERE (CAST(:status AS text) IS NULL OR status = CAST(:status AS text)) AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))';
      const items = await db.query(
        'SELECT personnel_change_request_id AS "personnelChangeRequestId", employee_id AS "employeeId", change_item AS "changeItem", before_value_enc AS "beforeValue", after_value_enc AS "afterValue", request_reason AS "requestReason", status AS "status", reject_reason AS "rejectReason" FROM personnel_change_request ' + where + ' ORDER BY personnel_change_request_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM personnel_change_request ' + where,
        { status, employeeId: employeeRaw },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/personnel-change-requests')
  @HttpCode(200)
  async createPersonnelChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const changeItem = text(data['changeItem']);
    const afterValue = text(data['afterValue']);
    const requestReason = text(data['requestReason']);
    if (changeItem === null || afterValue === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 항목과 변경 후 값을 입력해 주세요.');
    }
    if (changeItem.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 항목은 100자 이하여야 합니다.');
    }
    const column = ITEM_COLUMNS[changeItem];
    if (column === undefined) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경할 수 없는 항목입니다.');
    }
    return transaction(async (db) => {
      // 가정: 변경 전 값은 신청자의 인사기록카드에서 변경 항목에 해당하는 컬럼 값
      const records = await db.query(
        'SELECT CAST(' + column + ' AS text) AS "beforeValue" FROM personnel_record WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (records.length === 0) {
        throw new ApiError(404, 'PERSONNEL_RECORD_NOT_FOUND', '신청자의 인사기록카드가 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO personnel_change_request (employee_id, change_item, before_value_enc, after_value_enc, request_reason, status, created_at, updated_at) VALUES (CAST(:userId AS bigint), :changeItem, :beforeValue, :afterValue, :requestReason, :status, now(), now()) RETURNING personnel_change_request_id AS "personnelChangeRequestId", status AS "status"',
        {
          userId: user.id,
          changeItem,
          beforeValue: records[0]['beforeValue'],
          afterValue,
          requestReason,
          status: '신청',
        },
      );
      return rows[0];
    });
  }

  @Post('/personnel-change-requests/:personnelChangeRequestId/review')
  @HttpCode(200)
  async reviewPersonnelChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const idRaw = req.params['personnelChangeRequestId'];
    if (!/^[0-9]+$/.test(idRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 번호가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const status = text(data['status']);
    const rejectReason = text(data['rejectReason']);
    if (status !== '승인' && status !== '반려') {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 또는 반려를 선택해 주세요.');
    }
    if (status === '반려' && rejectReason === null) {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT employee_id AS "employeeId", change_item AS "changeItem", before_value_enc AS "beforeValue", after_value_enc AS "afterValue", status AS "status" FROM personnel_change_request WHERE personnel_change_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idRaw },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PERSONNEL_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      const request = found[0];
      if (request['status'] !== '신청') {
        throw new ApiError(409, 'PERSONNEL_CHANGE_REQUEST_ALREADY_PROCESSED', '이미 ' + String(request['status']) + ' 처리된 신청 건입니다.');
      }
      let appliedPersonnelRecordId: number | null = null;
      if (status === '승인') {
        const column = ITEM_COLUMNS[String(request['changeItem'])];
        if (column === undefined) {
          throw new ApiError(400, 'VALIDATION_FAILED', '반영할 수 없는 변경 항목입니다.');
        }
        const applied = await db.query(
          'UPDATE personnel_record SET ' + column + ' = :afterValue, updated_at = now() WHERE employee_id = CAST(:employeeId AS bigint) RETURNING personnel_record_id AS "personnelRecordId"',
          { afterValue: request['afterValue'], employeeId: String(request['employeeId']) },
        );
        if (applied.length === 0) {
          throw new ApiError(404, 'PERSONNEL_RECORD_NOT_FOUND', '신청자의 인사기록카드가 없습니다.');
        }
        appliedPersonnelRecordId = Number(applied[0]['personnelRecordId']);
        // 가정: 변경 내용은 변경 항목과 변경 전후 값을 한 문장으로 적는다
        const content = String(request['changeItem']) + ': ' + String(request['beforeValue'] ?? '') + ' -> ' + String(request['afterValue']);
        await db.execute(
          'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at) VALUES (CAST(:userId AS bigint), :targetType, CAST(:targetId AS bigint), :changeType, now(), :content, now(), now())',
          {
            userId: user.id,
            targetType: 'personnel_record',
            targetId: String(appliedPersonnelRecordId),
            changeType: '인사정보 변경 승인',
            content,
          },
        );
      }
      const updated = await db.query(
        'UPDATE personnel_change_request SET status = :status, reject_reason = :rejectReason, reviewer_id = CAST(:userId AS bigint), reviewed_at = now(), updated_at = now() WHERE personnel_change_request_id = CAST(:id AS bigint) RETURNING status AS "status", reviewed_at AS "reviewedAt", reject_reason AS "rejectReason"',
        { status, rejectReason: status === '반려' ? rejectReason : null, userId: user.id, id: idRaw },
      );
      const title = status === '승인' ? '인사정보 변경 신청이 승인되었습니다.' : '인사정보 변경 신청이 반려되었습니다.';
      const body = status === '승인' ? String(request['changeItem']) + ' 변경이 인사기록카드에 반영되었습니다.' : '반려 사유: ' + String(rejectReason);
      await db.execute(
        'INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at) VALUES (CAST(:recipientId AS bigint), :channel, :title, :content, :readStatus, :eventType, :targetType, CAST(:targetId AS bigint), now(), now())',
        {
          recipientId: String(request['employeeId']),
          channel: NOTIFY_CHANNEL,
          title,
          content: body,
          readStatus: '안읽음',
          eventType: 'PERSONNEL_CHANGE_REVIEW',
          targetType: 'PERSONNEL_CHANGE_REQUEST',
          targetId: idRaw,
        },
      );
      return { ...updated[0], appliedPersonnelRecordId };
    });
  }
}

