import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  Pairs,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['반려', '반려'],
];
const REVIEW_OPTIONS: [string, string][] = [
  ['승인', '승인'],
  ['반려', '반려'],
];
const ITEM_OPTIONS: [string, string][] = [
  ['주소', '주소'],
  ['주민등록번호', '주민등록번호'],
  ['보훈정보', '보훈정보'],
  ['병역정보', '병역정보'],
  ['채용구분', '채용구분'],
  ['채용비고', '채용비고'],
];

export default function FnSfr01202Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ status: string; employeeId: number | string }>({ status: '', employeeId: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [changeItem, setChangeItem] = useState('');
  const [afterValue, setAfterValue] = useState('');
  const [requestReason, setRequestReason] = useState('');
  const [reviewStatus, setReviewStatus] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/personnel-change-requests', role, undefined, { page, size: 20, status: applied.status, employeeId: applied.employeeId }),
    [page, applied.status, applied.employeeId, role],
  );

  const search = () => {
    setPage(0);
    setApplied({ status, employeeId });
  };
  const reset = () => {
    setStatus('');
    setEmployeeId('');
    setPage(0);
    setApplied({ status: '', employeeId: '' });
  };

  const openCreate = () => {
    setChangeItem('');
    setAfterValue('');
    setRequestReason('');
    setCreating(true);
  };

  const submitCreate = async () => {
    if (!changeItem) {
      throw new Error('변경 항목을 선택해 주세요.');
    }
    if (!afterValue.trim()) {
      throw new Error('변경 후 값을 입력해 주세요.');
    }
    await call('POST', '/personnel-change-requests', role, { changeItem, afterValue, requestReason });
    notify('인사정보 변경을 신청했습니다.');
    setCreating(false);
    reload();
  };

  const openDetail = (row: Row) => {
    setReviewStatus('');
    setRejectReason('');
    setSelected(row);
  };

  const submitReview = async () => {
    if (!selected) {
      return;
    }
    if (!reviewStatus) {
      throw new Error('승인 또는 반려를 선택해 주세요.');
    }
    if (reviewStatus === '반려' && !rejectReason.trim()) {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    await call('POST', '/personnel-change-requests/' + String(selected['personnelChangeRequestId']) + '/review', role, { status: reviewStatus, rejectReason });
    notify(reviewStatus === '승인' ? '변경 신청을 승인했습니다.' : '변경 신청을 반려했습니다.');
    setSelected(null);
    reload();
  };

  if (selected) {
    const canReview = selected['status'] === '신청';
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>신청 내용</h2>
          <Pairs
            items={[
              ['신청 임직원', <RefNameCell key="emp" role={role} value={selected['employeeId']} />],
              ['변경 항목', String(selected['changeItem'] ?? '')],
              ['변경 전 값', String(selected['beforeValue'] ?? '')],
              ['변경 후 값', String(selected['afterValue'] ?? '')],
              ['신청 사유', String(selected['requestReason'] ?? '')],
              ['승인 처리 상태', <Badge key="st" value={selected['status']} />],
              ['반려 사유', String(selected['rejectReason'] ?? '')],
            ]}
          />
        </section>
        {canReview && role === '인사 담당자' ? (
          <section className="box">
            <h2>검토</h2>
            <Form onSubmit={submitReview} submit="처리하기" note="처리한 뒤에는 되돌릴 수 없고, 승인하면 인사기록카드에 바로 반영되며 신청자에게 결과가 알림으로 전달됩니다.">
              <Field label="승인 처리 상태" required>
                <Select value={reviewStatus} onChange={setReviewStatus} options={REVIEW_OPTIONS} />
              </Field>
              <Field label="반려 사유" hint="반려할 때는 반드시 입력해 주세요." wide>
                <TextInput value={rejectReason} onChange={setRejectReason} multiline />
              </Field>
            </Form>
          </section>
        ) : null}
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>인사정보 변경 신청</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="승인 처리 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="신청 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          {role === '임직원' ? <button onClick={openCreate}>변경 신청</button> : null}
        </Band>
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          columns={[
            { key: 'employeeId', label: '신청 임직원', render: (row) => <RefNameCell role={role} value={row['employeeId']} /> },
            { key: 'changeItem', label: '변경 항목' },
            { key: 'afterValue', label: '변경 후 값' },
            { key: 'requestReason', label: '신청 사유' },
            { key: 'status', label: '승인 처리 상태', render: (row) => <Badge value={row['status']} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={openDetail}
          empty="아직 변경 신청 내역이 없습니다. 임직원이 변경을 신청하면 이곳에 나타납니다."
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="인사정보 변경 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="신청하기">
            <Field label="변경 항목" required>
              <Select value={changeItem} onChange={setChangeItem} options={ITEM_OPTIONS} />
            </Field>
            <Field label="변경 후 값(암호화)" required wide>
              <TextInput value={afterValue} onChange={setAfterValue} multiline />
            </Field>
            <Field label="신청 사유" wide>
              <TextInput value={requestReason} onChange={setRequestReason} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}

import { RefName } from '../kit';

function RefNameCell({ role, value }: { role: string; value: unknown }) {
  return <RefName table="employee" role={role} value={value} />;
}
